import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { PieChart, Pie, Cell, BarChart, Bar, LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';

const Analytics = ({ token }) => {
  const [stats, setStats] = useState({
    totalEntries: 0,
    totalAmount: 0,
    anomalies: 0,
    categories: {},
    recentEntries: [],
    timelineData: []
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchAnalytics();
  }, []);

  const fetchAnalytics = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/ledger-entries?page=1&per_page=1000', {
        headers: { Authorization: `Bearer ${token}` }
      });

      const entries = response.data.entries || [];
      const totalEntries = entries.length;
      const totalAmount = entries.reduce((sum, entry) => sum + entry.amount, 0);
      const anomalies = entries.filter(entry => entry.is_anomaly).length;

      // Category breakdown
      const categories = {};
      entries.forEach(entry => {
        categories[entry.category] = (categories[entry.category] || 0) + entry.amount;
      });

      // Timeline data (group by date)
      const timelineMap = {};
      entries.forEach(entry => {
        const date = entry.date;
        if (!timelineMap[date]) {
          timelineMap[date] = { date, normal: 0, anomaly: 0 };
        }
        if (entry.is_anomaly) {
          timelineMap[date].anomaly += 1;
        } else {
          timelineMap[date].normal += 1;
        }
      });
      const timelineData = Object.values(timelineMap).sort((a, b) => new Date(a.date) - new Date(b.date)).slice(-10);

      setStats({
        totalEntries,
        totalAmount,
        anomalies,
        categories,
        recentEntries: entries.slice(0, 5),
        timelineData
      });
      setLoading(false);
    } catch (error) {
      console.error('Error fetching analytics:', error);
      setLoading(false);
    }
  };

  const formatCurrency = (amount) => {
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR'
    }).format(amount);
  };

  if (loading) {
    return (
      <div className="page-content">
        <div className="loading">Loading analytics...</div>
      </div>
    );
  }

  // Prepare chart data
  const pieData = [
    { name: 'Normal', value: stats.totalEntries - stats.anomalies, color: '#10b981' },
    { name: 'Anomalies', value: stats.anomalies, color: '#ef4444' }
  ];

  const categoryData = Object.entries(stats.categories).map(([name, value]) => ({
    name: name.charAt(0).toUpperCase() + name.slice(1),
    amount: value
  }));

  const COLORS = ['#10b981', '#ef4444', '#3b82f6', '#f59e0b', '#8b5cf6', '#ec4899'];

  return (
    <div className="page-content">
      {/* Stats Cards */}
      <div className="stats-grid">
        <div className="stat-card">
          <div className="stat-icon">📊</div>
          <div className="stat-content">
            <h3>Total Entries</h3>
            <div className="stat-number">{stats.totalEntries}</div>
          </div>
        </div>

        <div className="stat-card">
          <div className="stat-icon">💰</div>
          <div className="stat-content">
            <h3>Total Amount</h3>
            <div className="stat-number">{formatCurrency(stats.totalAmount)}</div>
          </div>
        </div>

        <div className="stat-card anomaly">
          <div className="stat-icon">⚠️</div>
          <div className="stat-content">
            <h3>Anomalies</h3>
            <div className="stat-number">{stats.anomalies}</div>
          </div>
        </div>

        <div className="stat-card">
          <div className="stat-icon">📈</div>
          <div className="stat-content">
            <h3>Anomaly Rate</h3>
            <div className="stat-number">
              {stats.totalEntries > 0 ? ((stats.anomalies / stats.totalEntries) * 100).toFixed(1) : 0}%
            </div>
          </div>
        </div>
      </div>

      {/* ML Process Flow Diagram */}
      <div className="card">
        <h2>🤖 Machine Learning Detection Process</h2>
        <div className="ml-process-flow">
          <div className="process-step">
            <div className="step-icon">📥</div>
            <div className="step-content">
              <h3>1. Data Input</h3>
              <p>Transaction submitted via form or CSV upload</p>
            </div>
          </div>
          <div className="process-arrow">→</div>

          <div className="process-step">
            <div className="step-icon">🔧</div>
            <div className="step-content">
              <h3>2. Feature Extraction</h3>
              <p>Amount, Category, Description Length, Log Scale</p>
            </div>
          </div>
          <div className="process-arrow">→</div>

          <div className="process-step">
            <div className="step-icon">🧠</div>
            <div className="step-content">
              <h3>3. ML Model (Isolation Forest)</h3>
              <p>Analyzes patterns & detects outliers</p>
            </div>
          </div>
          <div className="process-arrow">→</div>

          <div className="process-step">
            <div className="step-icon">✅</div>
            <div className="step-content">
              <h3>4. Classification</h3>
              <p>Normal or Anomaly</p>
            </div>
          </div>
          <div className="process-arrow">→</div>

          <div className="process-step">
            <div className="step-icon">📧</div>
            <div className="step-content">
              <h3>5. Alert</h3>
              <p>Email notification if anomaly detected</p>
            </div>
          </div>
        </div>
      </div>

      {/* Charts Row */}
      <div className="charts-grid">
        {/* Anomaly Distribution Pie Chart */}
        <div className="card chart-card">
          <h2>📊 Anomaly Distribution</h2>
          {stats.totalEntries > 0 ? (
            <ResponsiveContainer width="100%" height={300}>
              <PieChart>
                <Pie
                  data={pieData}
                  cx="50%"
                  cy="50%"
                  labelLine={false}
                  label={({ name, percent }) => `${name}: ${(percent * 100).toFixed(0)}%`}
                  outerRadius={100}
                  fill="#8884d8"
                  dataKey="value"
                >
                  {pieData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
          ) : (
            <p style={{ textAlign: 'center', padding: '2rem' }}>No data available</p>
          )}
        </div>

        {/* Category Breakdown Bar Chart */}
        <div className="card chart-card">
          <h2>💼 Category Breakdown</h2>
          {categoryData.length > 0 ? (
            <ResponsiveContainer width="100%" height={300}>
              <BarChart data={categoryData}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="name" />
                <YAxis />
                <Tooltip formatter={(value) => formatCurrency(value)} />
                <Bar dataKey="amount" fill="#3b82f6" />
              </BarChart>
            </ResponsiveContainer>
          ) : (
            <p style={{ textAlign: 'center', padding: '2rem' }}>No data available</p>
          )}
        </div>
      </div>

      {/* Timeline Chart */}
      <div className="card">
        <h2>📅 Transaction Timeline (Last 10 Days)</h2>
        {stats.timelineData.length > 0 ? (
          <ResponsiveContainer width="100%" height={300}>
            <LineChart data={stats.timelineData}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="date" />
              <YAxis />
              <Tooltip />
              <Legend />
              <Line type="monotone" dataKey="normal" stroke="#10b981" strokeWidth={2} name="Normal Transactions" />
              <Line type="monotone" dataKey="anomaly" stroke="#ef4444" strokeWidth={2} name="Anomalies" />
            </LineChart>
          </ResponsiveContainer>
        ) : (
          <p style={{ textAlign: 'center', padding: '2rem' }}>No timeline data available</p>
        )}
      </div>

      {/* ML Model Info */}
      <div className="card">
        <h2>🔬 Model Information</h2>
        <div className="model-info-grid">
          <div className="info-item">
            <strong>Algorithm:</strong>
            <span>Isolation Forest</span>
          </div>
          <div className="info-item">
            <strong>Features Used:</strong>
            <span>6 (Amount, Category, Description Length, Log Scale, Amount in Lakhs, High Amount Flag)</span>
          </div>
          <div className="info-item">
            <strong>Training Data:</strong>
            <span>{stats.totalEntries} transactions</span>
          </div>
          <div className="info-item">
            <strong>Contamination Rate:</strong>
            <span>10% (Expected anomaly percentage)</span>
          </div>
          <div className="info-item">
            <strong>Model Status:</strong>
            <span className={stats.totalEntries >= 10 ? 'status-active' : 'status-inactive'}>
              {stats.totalEntries >= 10 ? '✅ Active (ML-based)' : '⚠️ Rule-based (Need 10+ entries)'}
            </span>
          </div>
          <div className="info-item">
            <strong>Detection Method:</strong>
            <span>{stats.totalEntries >= 10 ? 'Machine Learning' : 'Rule-based Fallback'}</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Analytics;
